alter table pw_order add column customer_confirm_deadline timestamp;
alter table pw_order add column customer_confirmed_at timestamp;
create table pw_order_rule (id bigint generated by default as identity primary key,customer_confirm_hours integer not null default 24,auto_complete_enabled boolean not null default true,updated_at timestamp not null default current_timestamp);
create table pw_after_sale (id bigint generated by default as identity primary key,after_sale_no varchar(40) not null unique,order_id bigint not null,customer_id bigint not null,reason_type varchar(32) not null,description varchar(1000) not null,after_sale_status varchar(24) not null default 'PENDING',result_type varchar(24),result_remark varchar(1000),handled_by bigint,handled_at timestamp,created_at timestamp not null default current_timestamp,updated_at timestamp not null default current_timestamp);
create index ix_pw_after_sale_order on pw_after_sale(order_id);
create index ix_pw_after_sale_status on pw_after_sale(after_sale_status);
create table pw_after_sale_proof (id bigint generated by default as identity primary key,after_sale_id bigint not null,proof_url varchar(512) not null,sort_no integer not null default 0,created_at timestamp not null default current_timestamp);
create table pw_after_sale_log (id bigint generated by default as identity primary key,after_sale_id bigint not null,action varchar(24) not null,from_status varchar(24),to_status varchar(24) not null,remark varchar(1000),operator_id bigint,created_at timestamp not null default current_timestamp);

