insert into pw_order_rule(customer_confirm_hours,auto_complete_enabled) select 24,true where not exists(select 1 from pw_order_rule);
insert into sys_role(name,code,description,enabled,built_in) select '普通用户','customer','用户订单中心角色',true,true where not exists(select 1 from sys_role where code='customer');
insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no) select null,'DIRECTORY','CustomerPortal','/customer','/index/index','我的服务','ri:user-heart-line',40 where not exists(select 1 from sys_menu where name='CustomerPortal');
insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no) select id,'MENU','CustomerOrders','orders','/customer/orders','我的订单','ri:file-list-2-line',1 from sys_menu where name='CustomerPortal' and not exists(select 1 from sys_menu where name='CustomerOrders');
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select p.id,'BUTTON',concat('CustomerOrders',a.suffix),a.title,a.mark,a.sort_no from sys_menu p join (select 'List' suffix,'查看本人订单' title,'customer:order:list' mark,1 sort_no union all select 'Detail','查看本人订单详情','customer:order:detail',2 union all select 'Confirm','确认服务完成','customer:order:confirm',3 union all select 'AfterSale','提交售后申请','customer:after-sale:create',4) a on 1=1 where p.name='CustomerOrders' and not exists(select 1 from sys_menu m where m.auth_mark=a.mark);
insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no) select id,'MENU','AfterSaleManage','after-sale-manage','/business/after-sale-manage','售后管理','ri:customer-service-line',10 from sys_menu where name='Business' and not exists(select 1 from sys_menu where name='AfterSaleManage');
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select p.id,'BUTTON',concat(p.name,a.suffix),a.title,a.mark,a.sort_no from sys_menu p join (select 'List' suffix,'查询售后' title,'business:after-sale:list' mark,1 sort_no union all select 'Detail','查看售后详情','business:after-sale:detail',2 union all select 'Handle','处理售后','business:after-sale:handle',3) a on 1=1 where p.name='AfterSaleManage' and not exists(select 1 from sys_menu m where m.auth_mark=a.mark);
insert into sys_role_menu(role_id,menu_id) select r.id,m.id from sys_role r cross join sys_menu m where r.code='customer' and (m.name in('CustomerPortal','CustomerOrders') or m.auth_mark like 'customer:%') and not exists(select 1 from sys_role_menu x where x.role_id=r.id and x.menu_id=m.id);
insert into sys_role_menu(role_id,menu_id) select r.id,m.id from sys_role r cross join sys_menu m where r.code='admin' and (m.name in('CustomerPortal','CustomerOrders','AfterSaleManage') or m.auth_mark like 'customer:%' or m.auth_mark like 'business:after-sale:%') and not exists(select 1 from sys_role_menu x where x.role_id=r.id and x.menu_id=m.id);
